def SBMCreateASSUMPTIONSVector(builder, data):
    return builder.CreateVectorOfTables(data)

def CreateASSUMPTIONSVector(builder, data):
    SBMCreateASSUMPTIONSVector(builder, data)

def SBMAddCOMMENT(builder, COMMENT):
    builder.PrependUOffsetTRelativeSlot(34, flatbuffers.number_types.UOffsetTFlags.py_type(COMMENT), 0)

def AddCOMMENT(builder, COMMENT):
    SBMAddCOMMENT(builder, COMMENT)

def SBMEnd(builder):
    return builder.EndObject()

def End(builder):
    return SBMEnd(builder)

import sbmFragment
try:
    from typing import List
except:
    pass

class SBMT(object):

    # SBMT
    def __init__(
        self,
        MESSAGE_ID = None,
        CREATION_DATE = None,
        ORIGINATOR = None,
        EVENT_TYPE = 0,
        OBJECT_CLASS = 0,
        EPOCH = None,
        TIME_SYSTEM = None,
        REF_FRAME = None,
        OBJECT_NAME = None,
        OBJECT_ID = None,
        NORAD_CAT_ID = 0,
        IMPACTOR_OBJECT_NAME = None,
        IMPACTOR_NORAD_CAT_ID = 0,
        TARGET_MASS_KG = 0.0,
        TARGET_L_C_M = 0.0,
        IMPACTOR_MASS_KG = 0.0,
        IMPACTOR_L_C_M = 0.0,
        RELATIVE_VELOCITY_M_PER_S = 0.0,
        CATASTROPHIC = False,
        PARENT_POSITION_X_KM = 0.0,
        PARENT_POSITION_Y_KM = 0.0,
        PARENT_POSITION_Z_KM = 0.0,
        PARENT_VELOCITY_X_KM_PER_S = 0.0,
        PARENT_VELOCITY_Y_KM_PER_S = 0.0,
        PARENT_VELOCITY_Z_KM_PER_S = 0.0,
        MIN_LC_M = 0.0,
        SEED = 0,
        MODEL_NAME = None,
        MODEL_VERSION = None,
        FRAGMENT_COUNT = 0,
        INPUT_MASS_KG = 0.0,
        OUTPUT_MASS_KG = 0.0,
        FRAGMENTS = None,
        ASSUMPTIONS = None,
        COMMENT = None,
    ):
        self.MESSAGE_ID = MESSAGE_ID  # type: Optional[str]
        self.CREATION_DATE = CREATION_DATE  # type: Optional[str]
        self.ORIGINATOR = ORIGINATOR  # type: Optional[str]
        self.EVENT_TYPE = EVENT_TYPE  # type: int
        self.OBJECT_CLASS = OBJECT_CLASS  # type: int
        self.EPOCH = EPOCH  # type: Optional[str]
        self.TIME_SYSTEM = TIME_SYSTEM  # type: Optional[str]
        self.REF_FRAME = REF_FRAME  # type: Optional[str]
        self.OBJECT_NAME = OBJECT_NAME  # type: Optional[str]
        self.OBJECT_ID = OBJECT_ID  # type: Optional[str]
        self.NORAD_CAT_ID = NORAD_CAT_ID  # type: int
        self.IMPACTOR_OBJECT_NAME = IMPACTOR_OBJECT_NAME  # type: Optional[str]
        self.IMPACTOR_NORAD_CAT_ID = IMPACTOR_NORAD_CAT_ID  # type: int
        self.TARGET_MASS_KG = TARGET_MASS_KG  # type: float
        self.TARGET_L_C_M = TARGET_L_C_M  # type: float
        self.IMPACTOR_MASS_KG = IMPACTOR_MASS_KG  # type: float
        self.IMPACTOR_L_C_M = IMPACTOR_L_C_M  # type: float
        self.RELATIVE_VELOCITY_M_PER_S = RELATIVE_VELOCITY_M_PER_S  # type: float
        self.CATASTROPHIC = CATASTROPHIC  # type: bool
        self.PARENT_POSITION_X_KM = PARENT_POSITION_X_KM  # type: float
        self.PARENT_POSITION_Y_KM = PARENT_POSITION_Y_KM  # type: float
        self.PARENT_POSITION_Z_KM = PARENT_POSITION_Z_KM  # type: float
        self.PARENT_VELOCITY_X_KM_PER_S = PARENT_VELOCITY_X_KM_PER_S  # type: float
        self.PARENT_VELOCITY_Y_KM_PER_S = PARENT_VELOCITY_Y_KM_PER_S  # type: float
        self.PARENT_VELOCITY_Z_KM_PER_S = PARENT_VELOCITY_Z_KM_PER_S  # type: float
        self.MIN_LC_M = MIN_LC_M  # type: float
        self.SEED = SEED  # type: int
        self.MODEL_NAME = MODEL_NAME  # type: Optional[str]
        self.MODEL_VERSION = MODEL_VERSION  # type: Optional[str]
        self.FRAGMENT_COUNT = FRAGMENT_COUNT  # type: int
        self.INPUT_MASS_KG = INPUT_MASS_KG  # type: float
        self.OUTPUT_MASS_KG = OUTPUT_MASS_KG  # type: float
        self.FRAGMENTS = FRAGMENTS  # type: Optional[List[sbmFragment.sbmFragmentT]]
        self.ASSUMPTIONS = ASSUMPTIONS  # type: Optional[List[Optional[str]]]
        self.COMMENT = COMMENT  # type: Optional[str]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpSbm = SBM()
        tmpSbm.Init(buf, pos)
        return cls.InitFromObj(tmpSbm)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpSbm):
        x = SBMT()
        x._UnPack(tmpSbm)
        return x

    # SBMT
    def _UnPack(self, SBM):
        if SBM is None:
            return
        self.MESSAGE_ID = SBM.MESSAGE_ID()
        self.CREATION_DATE = SBM.CREATION_DATE()
        self.ORIGINATOR = SBM.ORIGINATOR()
        self.EVENT_TYPE = SBM.EVENT_TYPE()
        self.OBJECT_CLASS = SBM.OBJECT_CLASS()
        self.EPOCH = SBM.EPOCH()
        self.TIME_SYSTEM = SBM.TIME_SYSTEM()
        self.REF_FRAME = SBM.REF_FRAME()
        self.OBJECT_NAME = SBM.OBJECT_NAME()
        self.OBJECT_ID = SBM.OBJECT_ID()
        self.NORAD_CAT_ID = SBM.NORAD_CAT_ID()
        self.IMPACTOR_OBJECT_NAME = SBM.IMPACTOR_OBJECT_NAME()
        self.IMPACTOR_NORAD_CAT_ID = SBM.IMPACTOR_NORAD_CAT_ID()
        self.TARGET_MASS_KG = SBM.TARGET_MASS_KG()
        self.TARGET_L_C_M = SBM.TARGET_L_C_M()
        self.IMPACTOR_MASS_KG = SBM.IMPACTOR_MASS_KG()
        self.IMPACTOR_L_C_M = SBM.IMPACTOR_L_C_M()
        self.RELATIVE_VELOCITY_M_PER_S = SBM.RELATIVE_VELOCITY_M_PER_S()
        self.CATASTROPHIC = SBM.CATASTROPHIC()
        self.PARENT_POSITION_X_KM = SBM.PARENT_POSITION_X_KM()
        self.PARENT_POSITION_Y_KM = SBM.PARENT_POSITION_Y_KM()
        self.PARENT_POSITION_Z_KM = SBM.PARENT_POSITION_Z_KM()
        self.PARENT_VELOCITY_X_KM_PER_S = SBM.PARENT_VELOCITY_X_KM_PER_S()
        self.PARENT_VELOCITY_Y_KM_PER_S = SBM.PARENT_VELOCITY_Y_KM_PER_S()
        self.PARENT_VELOCITY_Z_KM_PER_S = SBM.PARENT_VELOCITY_Z_KM_PER_S()
        self.MIN_LC_M = SBM.MIN_LC_M()
        self.SEED = SBM.SEED()
        self.MODEL_NAME = SBM.MODEL_NAME()
        self.MODEL_VERSION = SBM.MODEL_VERSION()
        self.FRAGMENT_COUNT = SBM.FRAGMENT_COUNT()
        self.INPUT_MASS_KG = SBM.INPUT_MASS_KG()
        self.OUTPUT_MASS_KG = SBM.OUTPUT_MASS_KG()
        if not SBM.FRAGMENTSIsNone():
            self.FRAGMENTS = []
            for i in range(SBM.FRAGMENTSLength()):
                if SBM.FRAGMENTS(i) is None:
                    self.FRAGMENTS.append(None)
                else:
                    sbmFragment_ = sbmFragment.sbmFragmentT.InitFromObj(SBM.FRAGMENTS(i))
                    self.FRAGMENTS.append(sbmFragment_)
        if not SBM.ASSUMPTIONSIsNone():
            self.ASSUMPTIONS = []
            for i in range(SBM.ASSUMPTIONSLength()):
                self.ASSUMPTIONS.append(SBM.ASSUMPTIONS(i))
        self.COMMENT = SBM.COMMENT()

    # SBMT
    def Pack(self, builder):
        if self.MESSAGE_ID is not None:
            MESSAGE_ID = builder.CreateString(self.MESSAGE_ID)
        if self.CREATION_DATE is not None:
            CREATION_DATE = builder.CreateString(self.CREATION_DATE)
        if self.ORIGINATOR is not None:
            ORIGINATOR = builder.CreateString(self.ORIGINATOR)
        if self.EPOCH is not None:
            EPOCH = builder.CreateString(self.EPOCH)
        if self.TIME_SYSTEM is not None:
            TIME_SYSTEM = builder.CreateString(self.TIME_SYSTEM)
        if self.REF_FRAME is not None:
            REF_FRAME = builder.CreateString(self.REF_FRAME)
        if self.OBJECT_NAME is not None:
            OBJECT_NAME = builder.CreateString(self.OBJECT_NAME)
        if self.OBJECT_ID is not None:
            OBJECT_ID = builder.CreateString(self.OBJECT_ID)
        if self.IMPACTOR_OBJECT_NAME is not None:
            IMPACTOR_OBJECT_NAME = builder.CreateString(self.IMPACTOR_OBJECT_NAME)
        if self.MODEL_NAME is not None:
            MODEL_NAME = builder.CreateString(self.MODEL_NAME)
        if self.MODEL_VERSION is not None:
            MODEL_VERSION = builder.CreateString(self.MODEL_VERSION)
        if self.FRAGMENTS is not None:
            FRAGMENTSlist = []
            for i in range(len(self.FRAGMENTS)):
                FRAGMENTSlist.append(self.FRAGMENTS[i].Pack(builder))
            SBMStartFRAGMENTSVector(builder, len(self.FRAGMENTS))
            for i in reversed(range(len(self.FRAGMENTS))):
                builder.PrependUOffsetTRelative(FRAGMENTSlist[i])
            FRAGMENTS = builder.EndVector()
        if self.ASSUMPTIONS is not None:
            ASSUMPTIONSlist = []
            for i in range(len(self.ASSUMPTIONS)):
                ASSUMPTIONSlist.append(builder.CreateString(self.ASSUMPTIONS[i]))
            SBMStartASSUMPTIONSVector(builder, len(self.ASSUMPTIONS))
            for i in reversed(range(len(self.ASSUMPTIONS))):
                builder.PrependUOffsetTRelative(ASSUMPTIONSlist[i])
            ASSUMPTIONS = builder.EndVector()
        if self.COMMENT is not None:
            COMMENT = builder.CreateString(self.COMMENT)
        SBMStart(builder)
        if self.MESSAGE_ID is not None:
            SBMAddMESSAGE_ID(builder, MESSAGE_ID)
        if self.CREATION_DATE is not None:
            SBMAddCREATION_DATE(builder, CREATION_DATE)
        if self.ORIGINATOR is not None:
            SBMAddORIGINATOR(builder, ORIGINATOR)
        SBMAddEVENT_TYPE(builder, self.EVENT_TYPE)
        SBMAddOBJECT_CLASS(builder, self.OBJECT_CLASS)
        if self.EPOCH is not None:
            SBMAddEPOCH(builder, EPOCH)
        if self.TIME_SYSTEM is not None:
            SBMAddTIME_SYSTEM(builder, TIME_SYSTEM)
        if self.REF_FRAME is not None:
            SBMAddREF_FRAME(builder, REF_FRAME)
        if self.OBJECT_NAME is not None:
            SBMAddOBJECT_NAME(builder, OBJECT_NAME)
        if self.OBJECT_ID is not None:
            SBMAddOBJECT_ID(builder, OBJECT_ID)
        SBMAddNORAD_CAT_ID(builder, self.NORAD_CAT_ID)
        if self.IMPACTOR_OBJECT_NAME is not None:
            SBMAddIMPACTOR_OBJECT_NAME(builder, IMPACTOR_OBJECT_NAME)
        SBMAddIMPACTOR_NORAD_CAT_ID(builder, self.IMPACTOR_NORAD_CAT_ID)
        SBMAddTARGET_MASS_KG(builder, self.TARGET_MASS_KG)
        SBMAddTARGET_L_C_M(builder, self.TARGET_L_C_M)
        SBMAddIMPACTOR_MASS_KG(builder, self.IMPACTOR_MASS_KG)
        SBMAddIMPACTOR_L_C_M(builder, self.IMPACTOR_L_C_M)
        SBMAddRELATIVE_VELOCITY_M_PER_S(builder, self.RELATIVE_VELOCITY_M_PER_S)
        SBMAddCATASTROPHIC(builder, self.CATASTROPHIC)
        SBMAddPARENT_POSITION_X_KM(builder, self.PARENT_POSITION_X_KM)
        SBMAddPARENT_POSITION_Y_KM(builder, self.PARENT_POSITION_Y_KM)
        SBMAddPARENT_POSITION_Z_KM(builder, self.PARENT_POSITION_Z_KM)
        SBMAddPARENT_VELOCITY_X_KM_PER_S(builder, self.PARENT_VELOCITY_X_KM_PER_S)
        SBMAddPARENT_VELOCITY_Y_KM_PER_S(builder, self.PARENT_VELOCITY_Y_KM_PER_S)
        SBMAddPARENT_VELOCITY_Z_KM_PER_S(builder, self.PARENT_VELOCITY_Z_KM_PER_S)
        SBMAddMIN_LC_M(builder, self.MIN_LC_M)
        SBMAddSEED(builder, self.SEED)
        if self.MODEL_NAME is not None:
            SBMAddMODEL_NAME(builder, MODEL_NAME)
        if self.MODEL_VERSION is not None:
            SBMAddMODEL_VERSION(builder, MODEL_VERSION)
        SBMAddFRAGMENT_COUNT(builder, self.FRAGMENT_COUNT)
        SBMAddINPUT_MASS_KG(builder, self.INPUT_MASS_KG)
        SBMAddOUTPUT_MASS_KG(builder, self.OUTPUT_MASS_KG)
        if self.FRAGMENTS is not None:
            SBMAddFRAGMENTS(builder, FRAGMENTS)
        if self.ASSUMPTIONS is not None:
            SBMAddASSUMPTIONS(builder, ASSUMPTIONS)
        if self.COMMENT is not None:
            SBMAddCOMMENT(builder, COMMENT)
        SBM = SBMEnd(builder)
        return SBM
